#!/usr/bin/env python3
"""Compute production metrics and refresh the auto-generated block in PROGRESS.md.

Counts what actually exists on disk. A chapter counts as complete only if its
file carries "**Status:** Complete" AND both its problems and solutions files exist.

  python3 scripts/progress.py            # print metrics and rewrite PROGRESS.md block
  python3 scripts/progress.py --no-tests # skip running pytest
"""

from __future__ import annotations

import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
BEGIN, END = "<!-- AUTO-METRICS:BEGIN -->", "<!-- AUTO-METRICS:END -->"
PLANNED_CHAPTERS = 25
PLANNED_CASES = 10
TARGET_DRILLS = 150


def chapters():
    out = []
    for f in sorted((ROOT / "textbook").glob("part_*/ch*.md")):
        n = re.match(r"ch(\d\d)", f.name).group(1)
        text = f.read_text()
        status = re.search(r"\*\*Status:\*\*\s*([A-Za-z ]+)", text)
        st = status.group(1).strip() if status else "Unknown"
        q = (ROOT / f"problems/questions/ch{n}_problems.md").exists()
        s = (ROOT / f"problems/solutions/ch{n}_solutions.md").exists()
        pending = len(re.findall(r"verification pending", text, flags=re.I))
        out.append({"ch": n, "file": str(f.relative_to(ROOT)), "status": st, "problems": q, "solutions": s,
                     "words": len(text.split()), "pending": pending,
                     "complete": st.lower().startswith("complete") and q and s})
    return out


def count_problems():
    total = 0
    for f in (ROOT / "problems/questions").glob("ch*_problems.md"):
        total += len(re.findall(r"^### Problem ", f.read_text(), flags=re.M))
    return total


def cases():
    out = []
    for d in sorted((ROOT / "cases/hypothetical").glob("case_*")):
        main = [p for p in d.glob("case_*.md") if "rubric" not in p.name]
        rubric = list(d.glob("*rubric*.md"))
        text = main[0].read_text() if main else ""
        modes = all(f"Mode {m}" in text for m in "ABCD")
        out.append({"case": d.name, "modes_ABCD": modes, "rubric": bool(rubric),
                    "model": bool(list(d.glob("*.py"))), "complete": bool(main) and modes and bool(rubric)})
    return out


def drills():
    bank = json.loads((ROOT / "training/daily_drills/drill_bank.json").read_text())["drills"]
    by_cat = {}
    for d in bank:
        by_cat[d["category"]] = by_cat.get(d["category"], 0) + 1
    return len(bank), by_cat


def sources():
    reg = (ROOT / "SOURCE_REGISTER.md").read_text()
    return {k: len(re.findall(rf"\|\s*{k}\s*\|", reg)) for k in ("VERIFIED-PRIMARY", "VERIFIED-SECONDARY", "PENDING")}


def run_tests():
    r = subprocess.run([sys.executable, "-m", "pytest", "-q", str(ROOT / "tests")], capture_output=True, text=True,
                       cwd=ROOT)
    last = [ln for ln in r.stdout.strip().splitlines() if ln.strip()][-1] if r.stdout.strip() else "no output"
    return r.returncode == 0, last


def render(run_pytests=True) -> str:
    ch = chapters()
    cs = cases()
    nd, cat = drills()
    src = sources()
    lines = [BEGIN, "", "_Generated by `scripts/progress.py`; do not edit by hand._", ""]
    lines.append(f"| Metric | Done | Target |")
    lines.append("|---|---|---|")
    lines.append(f"| Chapters complete | {sum(c['complete'] for c in ch)} | {PLANNED_CHAPTERS} |")
    lines.append(f"| Chapter files present (any status) | {len(ch)} | {PLANNED_CHAPTERS} |")
    lines.append(f"| End-of-chapter problems | {count_problems()} | {PLANNED_CHAPTERS * 10} |")
    lines.append(f"| Drills in bank | {nd} ({', '.join(f'{k}:{v}' for k, v in sorted(cat.items()))}) | {TARGET_DRILLS}+ |")
    lines.append(f"| CRE cases complete (Modes A-D + rubric) | {sum(c['complete'] for c in cs)} | {PLANNED_CASES} |")
    lines.append(f"| Python modules in sdesk | {len(list((ROOT / 'models/python/sdesk').glob('*.py')))} | — |")
    lines.append(f"| Excel workbooks | {len(list((ROOT / 'models/excel').glob('*.xlsx')))} | — |")
    lines.append(f"| SQL files | {len(list((ROOT / 'models/sql').glob('*.sql')))} | — |")
    lines.append(f"| Sources verified (primary / secondary) | {src['VERIFIED-PRIMARY']} / {src['VERIFIED-SECONDARY']} | — |")
    lines.append(f"| Sources pending verification | {src['PENDING']} | 0 |")
    if run_pytests:
        ok, summary = run_tests()
        lines.append(f"| Test suite | {'PASS' if ok else 'FAIL'}: {summary} | all pass |")
    lines += ["", "| Chapter | Status | Words | Problems | Solutions | 'Verification pending' flags |",
              "|---|---|---|---|---|---|"]
    for c in ch:
        lines.append(f"| {c['ch']} | {c['status']} | {c['words']:,} | {'yes' if c['problems'] else 'no'} | "
                     f"{'yes' if c['solutions'] else 'no'} | {c['pending']} |")
    lines += ["", "| Case | Modes A–D | Rubric | Model | Complete |", "|---|---|---|---|---|"]
    for c in cs:
        lines.append(f"| {c['case']} | {'yes' if c['modes_ABCD'] else 'no'} | {'yes' if c['rubric'] else 'no'} | "
                     f"{'yes' if c['model'] else 'no'} | {'yes' if c['complete'] else 'no'} |")
    lines += ["", END]
    return "\n".join(lines)


def main():
    block = render(run_pytests="--no-tests" not in sys.argv)
    p = ROOT / "PROGRESS.md"
    text = p.read_text() if p.exists() else f"# Progress\n\n{BEGIN}\n{END}\n"
    if BEGIN in text:
        text = re.sub(re.escape(BEGIN) + ".*?" + re.escape(END), block, text, flags=re.S)
    else:
        text += "\n" + block + "\n"
    p.write_text(text)
    print(block)


if __name__ == "__main__":
    main()
